package de.mika.promptwerk;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.io.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class Revision29Tests {
 MainActivity a;
 @Before public void setup(){RuntimeEnvironment.getApplication().getSharedPreferences("library",0).edit().clear().commit();a=Robolectric.buildActivity(MainActivity.class).setup().get();}
 @After public void close(){a.onDestroy();}
 @Test public void newEntryNeverTouchesWorkingDraft(){a.editor.setText("Altes Projekt");a.newEntry();assertEquals("Altes Projekt",a.editor.getText().toString());assertNotNull(a.entryWindow);assertEquals("",a.entryWindow.text.getText().toString());assertFalse(a.entryWindow.reading);a.entryWindow.requestClose();assertEquals("Altes Projekt",a.editor.getText().toString());}
 @Test public void newPromptParksOldDraftAcrossRestart()throws Exception{a.editor.setText("Nicht verlieren");a.newPrompt();assertEquals("",a.editor.getText().toString());assertEquals("Nicht verlieren",new JSONArray(a.prefs.getString("parkedDrafts","[]")).getJSONObject(0).getString("text"));a.undo();assertEquals("Nicht verlieren",a.editor.getText().toString());}
 @Test public void conversionKeepsIdentityMetadataAndAttachments(){MainActivity.Item it=a.items.get(0);String id=it.id,text=it.text;it.star=true;it.archived=true;String previous=it.type;a.convertItem(it);assertNotEquals(previous,it.type);assertEquals(id,it.id);assertEquals(text,it.text);assertTrue(it.star&&it.archived);a.convertItem(it);assertEquals(previous,it.type);}
 @Test public void optimizerKeepsOriginalAndIsIdempotent(){String value="Analysiere Umsatz 2026; keine erfundenen Zahlen.";String result=PromptOptimizer.optimize(value);assertTrue(result.contains(value));assertTrue(result.contains("tatsächlich verfügbar"));assertEquals(result,PromptOptimizer.optimize(result));a.editor.setText(value);a.optimize(value,new ArrayList<>());assertEquals(value,a.editor.getText().toString());assertTrue(allText(ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView()).contains("AUFTRAG UND KONTEXT"));}
 @Test public void driveIntentTargetsDriveWithReadOnlyZipGrant()throws Exception{android.net.Uri u=android.net.Uri.parse("content://de.mika.promptwerk.attachments/backup/12345678-1234-1234-1234-123456789012.zip");Intent i=a.driveIntent(u);assertEquals("com.google.android.apps.docs",i.getPackage());assertEquals(Intent.ACTION_SEND,i.getAction());assertEquals("application/zip",i.getType());assertEquals(u,i.getParcelableExtra(Intent.EXTRA_STREAM));assertTrue((i.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0);assertEquals(0,i.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}
 @Test public void ideasPersistSeparatelyAndRestoreDoesNotOverwrite()throws Exception{a.editor.setText("Prompt bleibt");IdeaPad pad=new IdeaPad(a);pad.show();pad.text.setText("Spontane Projektidee");assertEquals("Spontane Projektidee",new JSONObject(a.prefs.getString("ideas","{}")).getString("Allgemein"));assertEquals("Prompt bleibt",a.editor.getText().toString());JSONObject imported=new JSONObject().put("ideas",new JSONObject().put("Allgemein","Andere Idee"));a.restoreExtras(imported);JSONObject restored=new JSONObject(a.prefs.getString("ideas","{}"));assertEquals(2,restored.length());assertEquals("Spontane Projektidee",restored.getString("Allgemein"));}
 @Test public void zipContainsIdeasAndParkedAttachments()throws Exception{a.editor.setText("Parken");a.newPrompt();a.prefs.edit().putString("ideas","{\"Projekt\":\"Gedanke\"}").commit();JSONObject manifest=new JSONObject().put("format","promptwerk").put("version",3).put("items",a.data()).put("ideas",new JSONObject(a.prefs.getString("ideas","{}"))).put("parkedDrafts",new JSONArray(a.prefs.getString("parkedDrafts","[]")));File zip=new File(a.getCacheDir(),"test.zip");a.buildBackup(zip,manifest,a.backupFiles());try(java.util.zip.ZipFile f=new java.util.zip.ZipFile(zip)){String json=new String(f.getInputStream(f.getEntry("promptwerk.json")).readAllBytes(),"UTF-8");assertTrue(json.contains("Gedanke"));assertTrue(json.contains("Parken"));}}
 @Test @GraphicsMode(GraphicsMode.Mode.NATIVE) public void screenshot360()throws Exception{View v=a.findViewById(android.R.id.content);v.measure(View.MeasureSpec.makeMeasureSpec(360,1073741824),View.MeasureSpec.makeMeasureSpec(800,1073741824));v.layout(0,0,360,800);android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(360,800,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));try(OutputStream out=new FileOutputStream("tests/Promptwerk-2.9-Hauptbildschirm.png")){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
 @Test public void unsavedNewEntrySurvivesRecreation()throws Exception{a.newEntry();a.entryWindow.title.setText("Neues Projekt");a.entryWindow.text.setText("Eigener Text");String state=a.entryWindow.state();a.entryWindow.dialog.dismiss();EntryWindow.restore(a,state);assertTrue(a.entryWindow.fresh);assertEquals("Eigener Text",a.entryWindow.text.getText().toString());int count=a.items.size();a.entryWindow.save();assertEquals(count+1,a.items.size());assertEquals("Eigener Text",a.sameName("Neues Projekt",null).text);}
 @Test public void backupProviderRejectsTraversalAndWrites()throws Exception{AttachmentProvider provider=Robolectric.buildContentProvider(AttachmentProvider.class).create().get();java.io.File dir=new java.io.File(a.getCacheDir(),"drive-backups");dir.mkdirs();String name=java.util.UUID.randomUUID()+".zip";try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name))){out.write(new byte[]{80,75});}android.net.Uri u=android.net.Uri.parse("content://de.mika.promptwerk.attachments/backup/"+name);assertEquals("application/zip",provider.getType(u));try(android.os.ParcelFileDescriptor fd=provider.openFile(u,"r")){assertEquals(2,fd.getStatSize());}try{provider.openFile(u,"w");fail();}catch(java.io.FileNotFoundException expected){}try{provider.openFile(android.net.Uri.parse("content://de.mika.promptwerk.attachments/backup/..%2Fsecret"),"r");fail();}catch(java.io.FileNotFoundException expected){}}
 String allText(View v){String s=v instanceof TextView?((TextView)v).getText().toString():"";if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s+=" "+allText(((ViewGroup)v).getChildAt(i));return s;}
}
